#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353LL;
        long long inv_cache[2000001];

        Mod998() {
            memset(inv_cache, -1, sizeof(inv_cache));
        }

        long long mod() {
            return MOD;
        }

        long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= mod()) res -= mod();
            return res;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += mod();
            return res;
        }

        long long mult(long long a, long long b) {
            return (a * b) % mod();
        }

        long long pow(long long base, long long exp) {
            long long result = 1;
            long long cur = base % mod();
            while (exp > 0) {
                if (exp & 1) result = mult(result, cur);
                cur = mult(cur, cur);
                exp >>= 1;
            }
            return result;
        }

        long long smallInv(long long a) {
            // Fermat's little theorem for prime modulus
            return pow(a, mod() - 2);
        }

        long long fInv(long long n) {
            // Precompute inverses up to n
            inv_cache[1] = 1;
            for (long long i = 2; i <= n; i++) {
                inv_cache[i] = mult(inv_cache[mod() % i], mod() - mod() / i);
            }
            return inv_cache[n];
        }

        long long ncr(long long n, long long r) {
            static vector<long long> fact, inv_fact;
            static long long maxN = -1;
            if (n > maxN) {
                fact.resize(n + 1);
                inv_fact.resize(n + 1);
                fact[0] = 1;
                for (long long i = 1; i <= n; i++) {
                    fact[i] = mult(fact[i - 1], i);
                }
                inv_fact[n] = smallInv(fact[n]);
                for (long long i = n - 1; i >= 0; i--) {
                    inv_fact[i] = mult(inv_fact[i + 1], i + 1);
                }
                maxN = n;
            }
            if (r > n || r < 0) return 0;
            return mult(fact[n], mult(inv_fact[r], inv_fact[n - r]));
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;

    // Precompute inverse of n + m
    long long sum_nm = n + m;
    long long inv_sum_nm = mod.smallInv(sum_nm);
    mod.fInv(sum_nm);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; ; i++) {
        if (p == 0) break;
        long long numerator = n - i;
        long long denominator = n + m - i;
        long long inv_denominator = mod.smallInv(denominator);
        p = mod.mult(p, numerator);
        p = mod.mult(p, inv_denominator);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.ncr(n, k);
        term = mod.mult(term, numPhases);
        term = mod.mult(term, phaseSize);
        if (k % 2 == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

